"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["77716"],{89450(e){e.exports=JSON.parse('{"id":"FIN-1070","slug":"cost-driver","term":"Cost Driver","also_known_as":[],"difficulty":"Advanced","definition":"A cost driver is a factor that causes a cost to change, such as the number of units produced, machine hours, orders processed or customer calls handled.","explanation":["Understanding cost drivers helps managers explain why costs rise and fall and assign costs more accurately to products and customers.","Different costs have different drivers. Raw material costs are driven by production volume. Purchasing department costs may be driven by the number of purchase orders. Customer service costs may be driven by the number of calls. Delivery costs may be driven by the number of deliveries or the distance travelled.","For example, a warehouse finds that its costs depend more on the number of separate orders picked than on the total weight shipped. Customers who place many small orders therefore cost more to serve than those placing a few large ones, even if they buy the same total amount.","Cost drivers are central to activity-based costing, which uses them to assign overheads. They also help managers reduce costs, by changing the driver itself, for example by encouraging customers to place fewer, larger orders, rather than simply cutting spending."],"note":"","total":1500,"prev":{"slug":"cost-center","term":"Cost Center"},"next":{"slug":"cost-of-capital","term":"Cost of Capital"}}')}}]);